// Minimal dependency-free bundler for opening the app via file:// as well as http.
// The source remains native ESM for Node tests; this concatenates the known graph
// into one classic IIFE because this project has no external dependencies.
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const files = [
  'src/core.js',
  'src/storage.js',
  'src/ui/format.js',
  'src/ui/waveform.js',
  'src/examples.js',
  'src/app.js',
];

const chunks = [];
for (const relativePath of files) {
  let source = await readFile(join(root, relativePath), 'utf8');
  source = source.replace(/^\s*import\s*\{[\s\S]*?\}\s*from\s*['"][^'"]+['"];?\s*$/gm, '');
  source = source.replace(/^\s*import\s+[A-Za-z0-9_]+\s+from\s*['"][^'"]+['"];?\s*$/gm, '');
  source = source.replace(/^export\s+/gm, '');
  chunks.push(`// ───────── ${relativePath} ─────────\n${source}`);
}

const banner = '/* Generated by tools/bundle.js. Edit src/ and run `npm run build` instead. */\n';
const output = `${banner}(() => {\n'use strict';\n\n${chunks.join('\n\n')}\n})();\n`;
await writeFile(join(root, 'app.bundle.js'), output);
console.log(`Built app.bundle.js (${Buffer.byteLength(output)} bytes)`);
